CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_assessmentapplicationwindow]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_assessmentapplicationwindow]
	(
		[apuk_applicationtypeid],
		[apuk_applicationtypeid_entitytype],
		[apuk_applicationtypeidname],
		[apuk_assessmentapplicationwindowid],
		[apuk_assessmentcategory],
		[apuk_assessmentmarketid],
		[apuk_assessmentmarketid_entitytype],
		[apuk_assessmentmarketidname],
		[apuk_assessmentwindowsid],
		[apuk_assessmentwindowsid_entitytype],
		[apuk_assessmentwindowsidname],
		[apuk_closingmonth],
		[apuk_credentialid],
		[apuk_credentialid_entitytype],
		[apuk_credentialidname],
		[apuk_dayclosing],
		[apuk_drsid],
		[apuk_drsid_entitytype],
		[apuk_drsidname],
		[apuk_forassessmentduring],
		[apuk_fromday],
		[apuk_frommonth],
		[apuk_name],
		[apuk_pathwaygroup],
		[apuk_pathwaygroupoption],
		[apuk_regionalteamid],
		[apuk_regionalteamid_entitytype],
		[apuk_regionalteamidname],
		[apuk_regionalteamidyominame],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_applicationtypeid],
		stg.[apuk_applicationtypeid_entitytype],
		stg.[apuk_applicationtypeidname],
		stg.[apuk_assessmentapplicationwindowid],
		stg.[apuk_assessmentcategory],
		stg.[apuk_assessmentmarketid],
		stg.[apuk_assessmentmarketid_entitytype],
		stg.[apuk_assessmentmarketidname],
		stg.[apuk_assessmentwindowsid],
		stg.[apuk_assessmentwindowsid_entitytype],
		stg.[apuk_assessmentwindowsidname],
		stg.[apuk_closingmonth],
		stg.[apuk_credentialid],
		stg.[apuk_credentialid_entitytype],
		stg.[apuk_credentialidname],
		stg.[apuk_dayclosing],
		stg.[apuk_drsid],
		stg.[apuk_drsid_entitytype],
		stg.[apuk_drsidname],
		stg.[apuk_forassessmentduring],
		stg.[apuk_fromday],
		stg.[apuk_frommonth],
		stg.[apuk_name],
		stg.[apuk_pathwaygroup],
		stg.[apuk_pathwaygroupoption],
		stg.[apuk_regionalteamid],
		stg.[apuk_regionalteamid_entitytype],
		stg.[apuk_regionalteamidname],
		stg.[apuk_regionalteamidyominame],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_assessmentapplicationwindow] stg
		LEFT JOIN [synapse_ce].[apuk_assessmentapplicationwindow] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
